from functools import wraps
import time

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """

    def wrapper(func):
        cache = {}

        @wraps(func)
        def cached_func(*args, **kwargs):
            # Calculate the cache key based on args and kwargs
            cache_key = (args, frozenset(kwargs.items()))

            if cache_key in cache:
                if timer(cache_key) < ttl:
                    # Return the cached result
                    return cache[cache_key]
                else:
                    # Remove the expired result
                    del cache[cache_key]
            else:
                # Call the original function and cache the result
                result = func(*args, **kwargs)
                if cache_key not in cache:
                    cache[cache_key] = (result, timer(cache_key))
                    if maxsize > 0:
                        while len(cache) > maxsize:
                            earliest_time, _ = min(cache.items(), key=lambda x: x[1][1])
                            del cache[earliest_time]
            return result

        return cached_func

    return wrapper

