def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
    if not isinstance(prior, InventoryValidator):
        raise TypeError("Input variable prior must be of type InventoryValidator")
    if not self.check_consistency():
        raise AssertionError("self is not consistent with the current inventory")
    if not prior.check_consistency():
        raise AssertionError("prior is not consistent with the current inventory")
    for file_id, prior_file in prior.get_files().items():
        if file_id not in self.get_files():
            raise ValueError("File id " + file_id + " not found in prior inventory")
        prior_file.validate(self.get_files()[file_id])

