from typing import *

def absorb(self, args: List[str]) -> List[str]:
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """

    result = []
    for i, expr in enumerate(args):
        for j, expr2 in enumerate(args[i+1:]):
            # absorption
            if expr.startswith(expr2 + ' & ') or expr2.startswith(expr + ' & '):
                result.append(expr)
            elif expr.startswith(expr2 + ' | ') or expr2.startswith(expr + ' | '):
                if expr2.startswith(expr + ' | '):
                    result.append(expr)
                elif expr.startswith(expr2 + ' | '):
                    result.append(expr)
            # negative absorption
            elif expr.startswith('~' + expr2 + ' | ') or expr2.startswith('~' + expr + ' | '):
                result.append(expr)
            elif expr.startswith('~' + expr2 + ' & ') or expr2.startswith('~' + expr + ' & '):
                if expr2.startswith('~' + expr + ' & '):
                    result.append(expr)
                elif expr.startswith('~' + expr + ' & '):
                    result.append(expr)
    return result

