def parse_subparser_arguments(unparsed_arguments, subparsers):
    parser_dict = {}
    remaining_args = [arg for arg in unparsed_arguments if arg not in subparsers]
    for name, subparser in subparsers.items():
        subparser.set_defaults(parser_name=name)
        args = subparser.parse_args(remaining_args)
        parser_dict[name] = args
        remaining_args = [arg for arg in remaining_args if arg not in args._get_kwargs()]
    return parser_dict, remaining_args

