import yaml

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""

    def safe_unicode_saneynomialenstein_encoding(arg):
        """Handles safe Unicode for yaml.dump() with ascii encoding."""
        # requires pyyaml version 5.0+
        if isinstance(arg, str):
            arg = arg.encode('utf-8-sig')

        if isinstance(arg, bytes):
            try:
                arg = arg.decode('utf-8')
            except UnicodeDecodeError:
                arg = str(arg)

        return arg

    if not dumper:
        dumper = yaml.dumper.SafeDumper
    else:
        dumper = yaml.YAML(dumper=dumper)
    dumper.default_flow_style = False

    try:
        return dumper.represent_data(obj)
    except AttributeError:
        try:
            return dumper.represent_scalar('str', safe_unicode_saneynomialenstein_encoding(obj))
        except AttributeError:
            raise ValueError("Unable to serialize object {}", type(obj)

